// #8060ad (4cfbf19e5cc11c71a68060ad) — «פרק השבוע» в «פרקי אבות», עבר QA 25.10.2026. Нативное приложение даты устройства не меняет,
// поэтому сезон проверяется в вебе (zichui-harabim.expo.app) подменой часов браузера: page.clock.setFixedTime + expires_at токена
// = fake + 1 ч (иначе приложение разлогинит; .qa/context.md «Технические заметки», хелпер ../_helpers/clock.ts).
// מה רצוי: реджект 21.10 rej_b8d4… — в каждую שבת сезона строка и метка «פרק השבוע» по לוח Hebcal (Израиль), включая сдвоенные
// 18.9.2027 «ג׳–ד׳» и 25.9.2027 «ה׳–ו׳» с меткой на обеих главах; вне сезона — «…ולכן עכשיו אין «פרק השבוע»…» (коммент 20.10, d38c3f4).
// Эталон дат — hebcal @hebcal/learning pirkeiAvot il=true (бриф .qa/research/4cfbf19e.md). Факт 25.10: все 11 дат совпали
// (скрины .qa/screenshots/8060ad-2510-*-mobile.png). Сессия — копия в контексте теста, файл .qa/auth/user1.json не меняется.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { setFixedTimeKeepingSession } from '../_helpers/clock';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

// ОБНОВЛЕНО 26.10.2026 (#70ef78 / 30e340e0, commit f881957, עבר QA 26.10): «…הסימון יחזור בשבוע של השבת הראשונה שאחרי פסח.»
// (было «…הסימון יחזור בשבת הראשונה שאחרי פסח.»). Неделя до первой שבת — tests/tehilim/th-06-avot-off-season-text-70ef78.spec.ts.
const OFF_SEASON = 'פרקי אבות נאמרים בשבתות שמפסח עד ראש השנה, ולכן עכשיו אין «פרק השבוע». הסימון יחזור בשבוע של השבת הראשונה שאחרי פסח.';

/** Дата (שבת, 09:00 Израиль) → ожидаемые главы; [] — нет «פרק השבוע» (вне сезона / חוה״מ / ר״ה). */
const CASES: { date: string; heb: string; chapters: string[] }[] = [
  { date: '2027-04-24', heb: 'י״ז ניסן (חוה״מ פסח)', chapters: [] },
  { date: '2027-05-01', heb: 'כ״ד ניסן', chapters: ['א׳'] },
  { date: '2027-05-08', heb: 'א׳ אייר', chapters: ['ב׳'] },
  { date: '2027-06-05', heb: 'כ״ט אייר', chapters: ['ו׳'] },
  { date: '2027-06-12', heb: 'ז׳ סיוון', chapters: ['א׳'] },
  { date: '2027-08-28', heb: 'כ״ה אב', chapters: ['ו׳'] },
  { date: '2027-09-04', heb: 'ב׳ אלול', chapters: ['א׳'] },
  { date: '2027-09-11', heb: 'ט׳ אלול', chapters: ['ב׳'] },
  { date: '2027-09-18', heb: 'ט״ז אלול', chapters: ['ג׳', 'ד׳'] },
  { date: '2027-09-25', heb: 'כ״ג אלול', chapters: ['ה׳', 'ו׳'] },
  { date: '2027-10-02', heb: 'א׳ תשרי (ראש השנה)', chapters: [] },
];

/** Открыть «פרקי אבות» на /tehilim и дождаться строки недели или заглушки вне сезона (переключение сегмента = пересчёт). */
async function openAvot(page: Page) {
  await page.goto('/tehilim');
  const avot = page.getByRole('button', { name: 'פרקי אבות', exact: true });
  await expect(avot).toBeVisible({ timeout: 15_000 });
  await page.getByRole('button', { name: 'תהילים', exact: true }).click();
  await avot.click();
  await expect(page.locator('#tehilim-avot-week, #tehilim-avot-off-season').first()).toBeVisible({ timeout: 10_000 });
}
/** Буквы глав, на карточках которых есть метка «פרק השבוע» (aria-label «פרקי אבות X — <начало> — פרק השבוע»). */
async function markedChapters(page: Page): Promise<string[]> {
  return page.locator('[aria-label^="פרקי אבות "]').evaluateAll((els) =>
    els.map((e) => e.getAttribute('aria-label') ?? '').filter((l) => /— פרק השבוע$/.test(l)).map((l) => l.split(' ')[2]));
}

test.describe('פרקי אבות — «פרק השבוע» по датам (подмена часов)', () => {
  for (const c of CASES) {
    const want = c.chapters.length ? c.chapters.join('+') : 'нет';
    test(`TH-04b ${c.date} (${c.heb}) → «פרק השבוע»: ${want} #8060ad #4cfbf19e @iphone @prod-safe`, async ({ page }) => {
      await setFixedTimeKeepingSession(page, new Date(`${c.date}T09:00:00+03:00`));
      await openAvot(page);
      // Не разлогинило (иначе проверка дат бессмысленна).
      await expect(page.getByText(/בואו נתחיל|מספר נייד/)).toHaveCount(0);

      if (c.chapters.length) {
        // Строка: «פרק השבוע: פרקי אבות א׳.» / сдвоенная «…ג׳–ד׳.» (en dash).
        await expect(page.locator('#tehilim-avot-week')).toHaveText(`פרק השבוע: פרקי אבות ${c.chapters.join('–')}.`);
        await expect(page.locator('#tehilim-avot-off-season')).toHaveCount(0);
        // Метка «פרק השבוע» — ровно на этих главах (сдвоенные — на обеих).
        await expect.poll(() => markedChapters(page)).toEqual(c.chapters);
      } else {
        await expect(page.locator('#tehilim-avot-off-season')).toHaveText(OFF_SEASON);
        await expect(page.locator('#tehilim-avot-week')).toHaveCount(0);
        await expect.poll(() => markedChapters(page)).toEqual([]);
      }
      // Все шесть глав на месте.
      await expect(page.locator('[aria-label^="פרקי אבות "]')).toHaveCount(6);
    });
  }
});
